/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if (event && event.payload && event.payload.patch !== undefined) {
		return {
			propName: "patch",
			value: event.payload.patch
		};
	}
	return null;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if (event && event.payload && event.payload.currentVersion !== undefined) {
		return {
			propName: "currentVersion",
			value: event.payload.currentVersion
		};
	}
	return null;
}

/**
* @param {params} params
* @param {api} params.api
