/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if (event && event.payload && event.payload.bulkPatch !== undefined) {
		return {
			propName: "bulkPatch",
			value: event.payload.bulkPatch
		};
	}
	return null;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	// Only load viewport on user action (relay from session creation includes currentVersion)
	// Page-load relay from e95926d6 only has {bulkPatch} - skip viewport load
	if (!event || !event.payload || !event.payload.currentVersion) return null;
	var bulkId = event.payload.bulkPatch;
	if (!bulkId) return null;
	return {
		viewportElementId: 'viewport_3',
		route: 'guided-app-update',
		fields: {
			table: 'sn_um_upgrade_sessions',
			sysId: bulkId,
			sessionType: 'bulk_app_update'
		},
		params: {
			experience: '68a44ca29f1312106548971b8a0a1ce2'
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	// Only switch tab on user action (relay from session creation includes currentVersion)
	// Page-load relay from e95926d6 only has {bulkPatch} - skip tab switch
	if (!event || !event.payload || !event.payload.currentVersion) return null;
	if (event.payload.bulkPatch) {
		return { propName: 'activeTab', value: 'guided_app_update' };
	}
	if (event.payload.patch) {
		return { propName: 'activeTab', value: 'guided_upgrade' };
	}
	return null;
}
